const raw = $input.first().json.output || '';

let j = {};

try {
  const m = raw.match(/\{[\s\S]*\}/);
  j = JSON.parse(m ? m[0] : raw);
} catch (e) {
  j = {};
}

const allowedCategories = [
  'grocery',
  'food',
  'electronics',
  'image',
  'excel',
  'other',
  'organizer',
  'all'
];

const category = allowedCategories.includes(j.category)
  ? j.category
  : 'other';

const mode = j.mode === 'all' || category === 'all'
  ? 'all'
  : 'smart';

const webhook = $('Chat Webhook').first().json;

const message =
  webhook.body?.message ||
  webhook.message ||
  '';

const sessionId =
  webhook.body?.sessionId ||
  webhook.sessionId ||
  'default';

return [{
  json: {
    mode,
    category,
    message,
    sessionId
  }
}];

const raw = $input.first().json.output || '';
let j = {};
try { const m = raw.match(/\{[\s\S]*\}/); j = JSON.parse(m ? m[0] : raw); } catch (e) {}
const cat = $('Parse Route').first().json.category;
const msg = $('Parse Route').first().json.message;
const table = (j.table && Array.isArray(j.table.columns) && Array.isArray(j.table.rows)) ? j.table : null;
const prompt = (j.image_prompt || msg).toString();
const image_url = (cat === 'image' || (cat === 'all' && j.image_prompt)) ? 'https://image.pollinations.ai/prompt/' + encodeURIComponent(prompt) + '?width=768&height=768&nologo=true&seed=' + Math.floor(Math.random() * 1e6) : '';
return [{ json: { timestamp: new Date().toISOString(), category: cat, title: String(j.title || msg).slice(0, 80), details: String(j.details || '').slice(0, 1000), extra: String(j.extra || '').slice(0, 300), image_url, table_json: table ? JSON.stringify(table) : '' } }];

const r = $('Build Record').first().json;
let table = null;
try { table = r.table_json ? JSON.parse(r.table_json) : null; } catch (e) {}
let agent_outputs = null;
try { agent_outputs = $('Combine Outputs').first().json.agent_outputs || null; } catch (e) {}
return [{ json: { reply: $input.first().json.output || 'Saved.', category: r.category, saved: { title: r.title, details: r.details }, table, image_url: r.image_url, timestamp: r.timestamp, table_json: r.table_json, agent_outputs } }];

const rows = $input.all().map(i => i.json).filter(r => r.category);
const counts = {};
for (const r of rows) counts[r.category] = (counts[r.category] || 0) + 1;
return [{ json: { counts, total: rows.length, rows: rows.slice(-60).reverse() } }];

const route = $('Parse Route').first().json;
if (route.mode !== 'all') return $input.all();

const agents = [
  '3 Grocery Planner Agent', '4 Grocery Budget Agent', '5 Recipe Agent', '6 Nutrition Agent',
  '7 Electronics Specs Agent', '8 Electronics Advisor Agent', '11 Image Prompt Agent',
  '12 Image Style Agent', '13 Excel Schema Agent', '14 Excel Formula Agent', '9 General Agent'
];

const agent_outputs = agents.map(name => {
  let out = '';
  try { out = String($(name).first().json.output || ''); } catch (e) { out = '(no output)'; }
  return { agent: name, output: out };
});

const text = agent_outputs.map(o => '## ' + o.agent + '\n' + o.output.slice(0, 700)).join('\n\n');
return [{ json: { mode: 'all', output: 'Combined outputs of all specialist agents:\n\n' + text, agent_outputs } }];
